"""Reproduce symbolic per-round proof instances from maintained templates."""
import hashlib,json,os
from pathlib import Path
S=Path(__file__).resolve().parent;R=S.parents[1];O=R/'outputs/mac-poseidon-call04';P=S/'project/ShielddSecurity';h=lambda b:hashlib.sha256(b).hexdigest();D=O/'rounds01.json';raw=D.read_bytes();assert h(raw)=='51d32bec96e244b484d8e65bbf67dbd238d1205161f9be4185a3b6165d6d559f';d=json.loads(raw);scopes={x['round']:x for x in d['selected_rounds']};records=[]
templates={i:(S/p).read_text() for i,p in [(0,'round-zero-proof-template.lean.txt'),(1,'round-proof-template.lean.txt')]}
for block in range(9):
 module=f'TransferPoseidonCall04Proof{block:02d}';lines=['-- GENERATED by generate_block_proofs.py; edit maintained template.']+['import ShielddSecurity.TransferPoseidonCall04'+x+f'{block:02d}' for x in ['ConsumerChecks','CoverageChecks','ProgramChecks']]+['import ShielddSecurity.PoseidonCallComposition04']
 if block==0:lines+=['import ShielddSecurity.TransferPoseidonAbsorb02SemanticProof01']
 lines+=['set_option maxHeartbeats 900000','set_option maxRecDepth 8192']
 for index in range(block*8,min(block*8+8,65)):
  scope=scopes[index];count=len(scope['arithmetic_row_indices'])
  floor=min(n['expression']['terms'][0][0] for n in scope['nodes'] if n['certificate']['constructor'] in ['square','product']);upper=max([n['expression']['terms'][0][0] for n in scope['nodes'] if n['certificate']['constructor'] in ['square','product']]+[n['certificate']['auxiliary'][0][0] for n in scope['nodes'] if n['certificate']['constructor']=='product'])
  text=templates[bool(index)]
  for a,b in [('@ROUND@',f'{index:02d}'),('@INDEX@',str(index)),('@FLOOR@',str(floor)),('@UPPER@',str(upper)),('@CEILING@',str(upper+1)),('@ROWCOUNT@',str(count))]:text=text.replace(a,b)
  cases='    have cases : '+' ∨ '.join(f'index={j}' for j in range(count))+' := by omega\n    rcases cases with '+'|'.join(['rfl']*count)+'\n'+''.join(f'    · exact row{j}_checked\n' for j in range(count))
  text=text.replace('@ROWCASES_AND_PROOFS@',cases.rstrip('\n'));lines.append(text.rstrip('\n'))
 b=('\n'.join(lines)+'\n').encode();p=P/(module+'.lean')
 if p.exists():assert p.read_bytes()==b,'symbolic template refresh changed source '+module
 else:
  tmp=p.with_suffix('.tmp');tmp.write_bytes(b);os.replace(tmp,p)
 records.append(dict(module=module,sha256=h(b),bytes=len(b)))
idx=1
while (O/f'block-proofs-generation{idx:02d}.json').exists():idx+=1
receipt=dict(generator_sha256=h(Path(__file__).read_bytes()),template_sha256={str(i):h(t.encode()) for i,t in templates.items()},descriptor_sha256=h(raw),sources=records,scope='symbolic round certificate and exact arithmetic row coverage/order per round')
(O/f'block-proofs-generation{idx:02d}.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(dict(sources=len(records),byte_identical=True)))
